const result = {};

for (const key in form) {
    if (this.EXCLUDE_FIELDS.includes(key)) continue; // Exclude these fields regardless of context
    if (form.hasOwnProperty(key) && form[key] !== "") {
        const titleCaseKey = key.charAt(0).toUpperCase() + key.slice(1);

        if (this._helpers._isBooleanField(key) && method === "POST") {
            result[titleCaseKey] = form[key] || false;
        } else if (key.includes("Date") && form[key]) {
            result[titleCaseKey] = this.utils.formatDate(form[key]);
        } else if (key === "workingDays" && form[key] && Object.values(form[key]).find(day => day)) {
            result[titleCaseKey] = this._helpers._convertWorkingDaysToString(form[key]);
        } else {
            result[titleCaseKey] = form[key];
        }
    }
}

return result;

if (!workingDays || typeof workingDays !== 'object') {
    return "";
}

return Object.entries(workingDays)
    .filter(([day, isActive]) => isActive)
    .map(([day]) => day)
    .join(", ");

const methodActionConfig = {
    "POST": "Insert",
    "PUT": "Update",
    "DELETE": "Delete"
};

const action = methodActionConfig[method];
const titleCased = entityTitle || entityType
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join('');

return `lonti_app_payroll_service_${entityType}_${action}${titleCased}`;

