try {
    const requestBody = {
        ...this._helpers._buildRequestBody(form, method),
        ...(method === "PUT" ? { "Id": selectedEntity.Id } : {}),
        ...additionalData
    };

    const endpoint = this._helpers._buildApiMethodName(method, entityType);
    const apiParams = method === "DELETE" ? { id: selectedEntity.Id } : {};
    const apiBody = method === "DELETE" ? undefined : requestBody;
    const headers = {
        "X-Authorization": this.$cookies.get("id_token")
    }

    let result;

    if (method === "DELETE") {
        result = await this.payrollAppApi[endpoint](apiParams, { headers });
    } else {
        result = await this.payrollAppApi[endpoint](apiParams, apiBody, { headers });
    }

    if (onSuccess) {
        try {
            await onSuccess(result);
        } catch (uiError) {
            console.error('onSuccess handler failed after successful operation', uiError);
        }
    }

    const actionText = this._helpers._getActionText(method);
    this.utils.toast(`Successfully ${actionText} ${entityName}`, result.status);

    return result;

} catch (reason) {
    if (onError) {
        onError(reason);
    }

    const errorMessage = reason.data?.message || `Failed to ${this._helpers._getActionText(method)} ${entityName}`;
    this.utils.toast(errorMessage, reason.data?.result || reason.status);

    throw reason;

} finally {
    if (onFinally) {
        onFinally();
    }
}

if (!selectedEntity || !selectedEntityName) {
    this.utils.toast("No entity selected for deletion", "ERROR");
    return false;
}

const entityDetails = this.utils.legacyGenerateEntityDetails({
    entity: selectedEntity,
    utils: this.utils
});

try {
    const response = await this.$modal.open("delete-entity-modal", {
        props: {
            EntityName: selectedEntityName,
            EntityDetails: entityDetails
        }
    });

    return response.result === "ok";

} catch (error) {
    return false;
}
